os.chdir(r"C:\Users\eric_rash\Desktop\DEV\Flint\.claude\worktrees\step1-triage")
sys.path.insert(0,"scripts"); import triage_model_pass as m
pas={r["key"]:r for r in csv.DictReader(open("data/triage_model_pass.csv",encoding="utf-8"))}
bad=0
for f in sorted(glob.glob("config/model_labels/*.csv")):
  for l in csv.DictReader(open(f,encoding="utf-8")):
