ath=re.compile(r"dexa|snapshot|catapult|pff|roster|bodyweight|testing.?results",re.I)
for r in pas.values():
    if r["tier"] in("A","B") and ath.search(r["path"]+" "+r["orig_name"]): print("ATH?",r["tier"],r["route"],r["path"][:110])

