import csv,os,glob,collections
os.chdir(r"C:\Users\eric_rash\Desktop\DEV\Flint\.claude\worktrees\step1-triage")
D={"Strength and power","Periodization and programming","Speed and sprint","Conditioning and energy systems","Rehab and return to play","Injury risk and prevention","Load monitoring and GPS","Testing and assessment","Recovery and sleep","Nutrition and body composition","Anatomy, physiology and biomechanics","Coaching, skill acquisition and constraints-led approach","Data, technology and reporting","Leadership, culture and psychology","Female athlete","Youth and development"}
R={"skip","already in Zotero","paper to Zotero","book","atomize","transcribe","catalog only"}
rv=list(csv.DictReader(open("data/_tmp/review_round1.csv",encoding="utf-8")))
print(len(rv),collections.Counter((r["file"],r["verdict"]) for r in rv))
lab={}
for f in glob.glob("config/model_labels/*.csv"):
    for r in csv.DictReader(open(f,encoding="utf-8")): lab[r["key"]]=f
pas={r["key"]:r for r in csv.DictReader(open("data/triage_model_pass.csv",encoding="utf-8"))}
bad=0
for r in rv:
    if r["verdict"]!="change": continue
    ds=[d.strip() for d in r["disciplines"].split(";") if d.strip()]
    probs=[]
    if r["key"] not in pas: probs.append("unknown key")
    if any(d not in D for d in ds): probs.append("disc "+str([d for d in ds if d not in D]))
    if r["route"] not in R: probs.append("route "+r["route"])
    if r["tier"] not in("B","C"): probs.append("tier")
    if r["candidate"] not in("yes","no"): probs.append("cand")
    if (r["tier"]=="C")!=(r["route"]=="skip"): probs.append("tier/route mismatch")
    if r["key"] not in lab: probs.append("no label file (rule-labelled)")
    if probs: bad+=1; print(r["key"][:10],probs,pas.get(r["key"],{}).get("path","")[:60])
print("bad",bad)

