import csv,os,collections,subprocess
os.chdir(r"C:\Users\eric_rash\Desktop\DEV\Flint\.claude\worktrees\step1-triage")
D={"Strength and power","Periodization and programming","Speed and sprint","Conditioning and energy systems","Rehab and return to play","Injury risk and prevention","Load monitoring and GPS","Testing and assessment","Recovery and sleep","Nutrition and body composition","Anatomy, physiology and biomechanics","Coaching, skill acquisition and constraints-led approach","Data, technology and reporting","Leadership, culture and psychology","Female athlete","Youth and development"}
R={"skip","already in Zotero","paper to Zotero","book","atomize","transcribe","catalog only"}
for n in (14,15,16):
    inp=[r["key"] for r in csv.DictReader(open(f"data/_tmp/todo_batch_{n}.csv",encoding="utf-8"))]
    out=list(csv.DictReader(open(f"config/model_labels/batch_{n}.csv",encoding="utf-8")))
    ok=[k for k in (r["key"] for r in out)]
    probs=[]
    if collections.Counter(ok)!=collections.Counter(inp): probs.append(f"keys mismatch in{len(inp)} out{len(ok)} missing{len(set(inp)-set(ok))} extra{len(set(ok)-set(inp))}")
    for r in out:
        ds=[d.strip() for d in r["disciplines"].split(";") if d.strip()]
        if any(d not in D for d in ds) or r["route"] not in R or r["tier"] not in("B","C") or r["candidate"] not in("yes","no") or (r["tier"]=="C")!=(r["route"]=="skip") or "\u2014" in r["reason"]:
            probs.append("bad row "+r["key"][:10])
    print(n,len(out),collections.Counter(r["candidate"] for r in out),probs[:5])
p=subprocess.run([os.path.expanduser("~/.local/bin/uv.exe"),"run","scripts/triage_model_pass.py"],capture_output=True,text=True)
print(p.stdout[-600:],p.stderr[-300:])

